const error = $input.first().json;

// Extract error details
const errorMessage = error.error?.message || 'Unknown error';
const errorNode = error.error?.node?.name || 'Unknown node';
const workflowName = error.execution?.workflowData?.name || 'GitHub Workflow Backup';
const executionId = error.execution?.id || 'unknown';
const timestamp = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

// Create detailed error report
const emailSubject = `🚨 n8n Backup Failed - ${timestamp}`;

const emailBody = `
<h2>n8n GitHub Backup Error Report</h2>

<p><strong>Timestamp:</strong> ${timestamp}</p>
<p><strong>Workflow:</strong> ${workflowName}</p>
<p><strong>Execution ID:</strong> ${executionId}</p>
<p><strong>Failed Node:</strong> ${errorNode}</p>

<h3>Error Details:</h3>
<pre style="background: #f5f5f5; padding: 10px; border-radius: 5px;">
${errorMessage}
</pre>

<h3>Stack Trace:</h3>
<pre style="background: #ffebee; padding: 10px; border-radius: 5px;">
${error.error?.stack || 'No stack trace available'}
</pre>

<hr>
<p><small>View execution in n8n: <a href="https://n8n-vps.chatsocialai.in/workflow/${error.execution?.workflowId}/executions/${executionId}">Open Execution</a></small></p>
`;

return [{
  json: {
    emailSubject: emailSubject,
    emailBody: emailBody,
    errorDetails: error
  }
}];

